package com.petlis.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.petlis.common.exception.BusinessException;
import com.petlis.common.security.AccessService;
import com.petlis.common.security.ReviewPermission;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;

/** Administrator explicitly confirms the existing Java adoption rules; never guesses identity or prices. */
@Service @RequiredArgsConstructor
public class LegacyOrderAdoptionPreparationService {
 private final FeatureStore store;private final AccessService access;private final LegacyOrderAdoptionService adoption;private final ReviewPermission review;
 public record Command(int doctorId,int laboratoryId,BigDecimal confirmedAmount,String expectedToken,String requestKey,boolean confirmed){}
 private Map<String,Boolean> policy(boolean lock){
  access.requireAdmin();var rows=store.jdbc().queryForList("SELECT config_value FROM lin_operational_config WHERE config_key='legacy-order-adoption' AND scope_type='GLOBAL' AND scope_id=0 AND status='ACTIVE'"+(lock?" FOR UPDATE":""));
  if(rows.size()!=1)return Map.of("legacyOrderAdoption",false,"legacyOrderAdoptionWrites",false);
  try{var j=new ObjectMapper().readTree(rows.get(0).get("config_value").toString());boolean enabled=j.path("enabled").isBoolean()&&j.path("enabled").asBoolean();return Map.of("legacyOrderAdoption",enabled,"legacyOrderAdoptionWrites",enabled&&j.path("writeEnabled").isBoolean()&&j.path("writeEnabled").asBoolean());}catch(com.fasterxml.jackson.core.JsonProcessingException error){throw new BusinessException(409,"旧单接入参数无效");}
 }
 @Transactional(readOnly=true) public Map<String,Boolean> capabilities(){return policy(false);}
 public void requireWrite(){if(!policy(false).get("legacyOrderAdoptionWrites"))throw new BusinessException(409,"旧单接入尚未开启");}
 private record Snapshot(Map<String,Object> parent,List<Map<String,Object>> details,List<Map<String,Object>> extension,boolean downstream){}
 private Snapshot snapshot(int id,boolean lock){if(id<1)throw new BusinessException(400,"送检单编号无效");var parent=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?"+(lock?" FOR UPDATE":""),id);var details=store.jdbc().queryForList("SELECT * FROM lin_lb_diagnosisdetail WHERE ListDiagnosisProjectId=? ORDER BY DiagnosisDetailId"+(lock?" FOR UPDATE":""),id);var extension=store.jdbc().queryForList("SELECT * FROM lin_order_extension WHERE order_id=?"+(lock?" FOR UPDATE":""),id);boolean downstream=Boolean.TRUE.equals(store.jdbc().queryForObject("SELECT EXISTS(SELECT 1 FROM lin_shipment WHERE order_id=?) OR EXISTS(SELECT 1 FROM lin_report_workflow WHERE order_id=?)",Boolean.class,id,id));return new Snapshot(parent,details,extension,downstream);}
 private String token(Snapshot s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(store.encode(new TreeMap<>(Map.of("parent",s.parent(),"details",s.details(),"extension",s.extension(),"downstream",s.downstream()))).getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException error){throw new IllegalStateException(error);}}
 private static int number(Object v){return v instanceof Number n?n.intValue():0;}
 private List<Map<String,Object>> doctors(int hospital){var result=store.jdbc().queryForList("SELECT u.id,u.username,u.nickname FROM lin_user u LEFT JOIN lin_doctor_profile p ON p.user_id=u.id WHERE u.hospital_id=? AND u.status='normal' AND (p.review_status IS NULL OR p.review_status='approved') AND (NOT EXISTS(SELECT 1 FROM lin_user_role r WHERE r.user_id=u.id AND r.is_active=1) OR EXISTS(SELECT 1 FROM lin_user_role r WHERE r.user_id=u.id AND r.is_active=1 AND r.role_code='DOCTOR')) ORDER BY u.id",hospital);result.removeIf(row->review.isLegacyReviewerId(number(row.get("id"))));for(var row:result){String username=Objects.toString(row.remove("username"),""),nickname=Objects.toString(row.remove("nickname"),"");row.put("name",nickname.isBlank()||nickname.equals(username)?username:nickname+"（"+username+"）");}return result;}
 private List<Map<String,Object>> laboratories(int id){return store.jdbc().queryForList("SELECT l.id,l.name FROM lin_laboratory l WHERE l.active=1 AND NOT EXISTS(SELECT 1 FROM lin_lb_diagnosisdetail d LEFT JOIN lin_lab_test lt ON lt.laboratory_id=l.id AND lt.test_type_id=d.InfoTestTypeId LEFT JOIN lin_lb_infotesttype t ON t.InfoTestTypeId=d.InfoTestTypeId WHERE d.ListDiagnosisProjectId=? AND d.IsActive=1 AND d.IsCheckPass=0 AND (lt.test_type_id IS NULL OR lt.active<>1 OR t.InfoTestTypeId IS NULL OR t.IsActive<>1)) ORDER BY l.id",id);}
 private Map<String,Object> describe(int id,Snapshot state){
  var p=state.parent();int hospital=number(p.get("InfoHospitalId"));var doctors=doctors(hospital);var labs=laboratories(id);var problems=new ArrayList<String>();
  if(!state.extension().isEmpty())problems.add("已接入统一审核，无需再次绑定");if(number(p.get("SampleStatus"))!=0)problems.add("只有待审核旧单可以接入");if(number(p.get("IsPayMoney"))==1)problems.add("已付款单据不能作为准备单接入");
  String barcode=Objects.toString(p.get("UserNO"),"").trim();if(!barcode.matches("[A-Za-z0-9][A-Za-z0-9_./ +%-]{1,62}[A-Za-z0-9]"))problems.add("请先通过编辑主单补全可扫描的样本号");else if(Boolean.TRUE.equals(store.jdbc().queryForObject("SELECT EXISTS(SELECT 1 FROM lin_lb_listdiagnosisproject WHERE UserNO=? AND ListDiagnosisProjectId<>?)",Boolean.class,barcode,id)))problems.add("样本号已被其他单据使用，请先核实");
  BigDecimal total=BigDecimal.ZERO;int effective=0;boolean downstream=state.downstream();for(var d:state.details())if(number(d.get("IsActive"))==1){if(number(d.get("IsSendMail"))==1||number(d.get("DiagnosisStatus"))==2)downstream=true;if(number(d.get("IsCheckPass"))==0){effective++;if(d.get("TestPrice")==null)problems.add("检测项目金额缺失");else{var price=new BigDecimal(d.get("TestPrice").toString());if(price.signum()<0)problems.add("检测项目金额不能为负数");total=total.add(price);}}}
  if(effective==0)problems.add("没有有效检测项目，请先维护明细");if(downstream)problems.add("已有物流或报告记录，不能作为新待审单接入");
  BigDecimal stored=p.get("TestFee")==null?null:new BigDecimal(p.get("TestFee").toString());int owner=number(p.get("CreateSampleId"));if(stored==null||stored.signum()<0||stored.compareTo(total)!=0&&!(owner==0&&stored.signum()==0))problems.add("原单总额与明细不一致，不能自动覆盖");
  if(doctors.isEmpty())problems.add("本院没有可用于送检的医生账号");if(owner>0&&doctors.stream().noneMatch(d->number(d.get("id"))==owner))problems.add("原医生身份不可用，请先核实账号归属");if(labs.isEmpty())problems.add("没有覆盖全部有效项目的已启用实验室");
  var response=new LinkedHashMap<String,Object>();response.put("orderId",id);response.put("orderNo",barcode);response.put("animalName",Objects.toString(p.get("AnimalName"),""));response.put("doctorName",Objects.toString(p.get("DoctorName"),""));response.put("hospitalName",Objects.toString(store.one("SELECT HospitalName FROM lin_lb_infohospital WHERE InfoHospitalId=?",hospital).get("HospitalName"),""));response.put("storedAmount",stored==null?"":stored.scale()<2?stored.setScale(2).toPlainString():stored.toPlainString());response.put("detailAmount",total.setScale(2).toPlainString());response.put("assignedDoctorId",owner);response.put("doctors",doctors);response.put("laboratories",labs);response.put("alreadyBound",!state.extension().isEmpty());response.put("fillsZeroAmount",stored!=null&&owner==0&&stored.signum()==0&&stored.compareTo(total)!=0);if(!state.extension().isEmpty()){var e=state.extension().get(0);var u=store.jdbc().queryForList("SELECT nickname,username FROM lin_user WHERE id=?",e.get("user_id"));var l=store.jdbc().queryForList("SELECT name FROM lin_laboratory WHERE id=?",e.get("laboratory_id"));response.put("boundDoctorName",u.isEmpty()?"未匹配":Objects.toString(u.get(0).get("nickname"),Objects.toString(u.get(0).get("username"),"")));response.put("boundLaboratoryName",l.isEmpty()?"未匹配":Objects.toString(l.get(0).get("name"),""));}response.put("problems",problems);response.put("ready",problems.isEmpty());response.put("editToken",token(state));return response;
 }
 @Transactional(readOnly=true) public Map<String,Object> preview(int id){if(!policy(false).get("legacyOrderAdoption"))throw new BusinessException(409,"旧单接入核对尚未开启");var result=describe(id,snapshot(id,false));result.put("writable",policy(false).get("legacyOrderAdoptionWrites"));return result;}
 @Transactional(isolation=Isolation.READ_COMMITTED) public Map<String,Object> prepare(int id,Command c){
  if(!policy(true).get("legacyOrderAdoptionWrites"))throw new BusinessException(409,"旧单接入尚未开启");
  if(c==null||!c.confirmed()||c.doctorId()<1||c.laboratoryId()<1||c.confirmedAmount()==null||c.confirmedAmount().signum()<0||c.confirmedAmount().scale()>2||c.expectedToken()==null||!c.expectedToken().matches("[a-f0-9]{64}")||c.requestKey()==null||!c.requestKey().matches("[A-Za-z0-9_-]{16,64}"))throw new BusinessException(400,"请明确选择医生、实验室并确认原金额");
  int actor=access.current().userId();store.one("SELECT id FROM lin_user WHERE id=? FOR UPDATE",actor);String canonical=store.encode(Map.of("orderId",id,"command",c));var prior=store.jdbc().queryForList("SELECT after_json FROM lin_audit_record WHERE actor_user_id=? AND resource_type='LEGACY_ORDER_ADOPTION_PREPARATION' AND request_id=? ORDER BY id DESC LIMIT 1",actor,c.requestKey());
  if(!prior.isEmpty())try{var saved=new ObjectMapper().readTree(prior.get(0).get("after_json").toString());if(!LegacyCanonicalRequest.same(canonical,saved.path("canonicalRequest").asText()))throw new BusinessException(409,"接入请求号已用于不同内容");return Map.of("orderId",id,"managed",true);}catch(com.fasterxml.jackson.core.JsonProcessingException error){throw new BusinessException(409,"接入请求记录无法核对");}
  var state=snapshot(id,true);if(!token(state).equals(c.expectedToken()))throw new BusinessException(409,"原单或明细已变化，请重新核对");var preview=describe(id,state);if(!Boolean.TRUE.equals(preview.get("ready")))throw new BusinessException(409,"原单尚不具备接入条件，请核对页面说明");
  @SuppressWarnings("unchecked")var doctors=(List<Map<String,Object>>)preview.get("doctors");@SuppressWarnings("unchecked")var labs=(List<Map<String,Object>>)preview.get("laboratories");
  if(doctors.stream().noneMatch(d->number(d.get("id"))==c.doctorId())||labs.stream().noneMatch(l->number(l.get("id"))==c.laboratoryId()))throw new BusinessException(409,"医生或实验室已不可用，请刷新选择");if(c.confirmedAmount().compareTo(new BigDecimal(preview.get("detailAmount").toString()))!=0)throw new BusinessException(409,"确认金额与当前明细不一致");
  adoption.submitPrepared(id,c.doctorId(),c.laboratoryId(),c.confirmedAmount());
  store.insert("INSERT INTO lin_audit_record(actor_user_id,action,resource_type,resource_id,request_id,after_json) VALUES(?,'LEGACY_ORDER_ADOPTION_CONFIRMED','LEGACY_ORDER_ADOPTION_PREPARATION',?,?,?)",actor,String.valueOf(id),c.requestKey(),store.encode(Map.of("canonicalRequest",canonical,"orderId",id)));return Map.of("orderId",id,"managed",true);
 }
}
